<section class="page-section"><div class="container"><div class="section-title"><div><p class="eyebrow">BỘ SƯU TẬP</p><h1>Chỗ ở yêu thích</h1></div></div><?php if(!$listings): ?><div class="empty-state"><h2>Danh sách đang trống</h2><p>Nhấn biểu tượng trái tim tại một chỗ ở để lưu lại.</p><a class="btn btn-primary" href="<?= e(url('/')) ?>">Khám phá</a></div><?php else: ?><div class="row"><?php foreach($listings as $listing): ?><div class="col-md-6 col-lg-4 mb-4"><article class="listing-card"><a href="<?= e(url('/listings/'.$listing['id'])) ?>"><img class="card-image" src="<?= e(image_url($listing['image_url'])) ?>" alt="<?= e($listing['title']) ?>"></a><button class="favorite-button is-saved" data-favorite="<?= (int)$listing['id'] ?>">♡</button><div class="card-body"><h3><a href="<?= e(url('/listings/'.$listing['id'])) ?>"><?= e($listing['title']) ?></a></h3><p><?= e($listing['city']) ?> · <?= e($listing['property_type']) ?></p><p class="price"><?= number_format((float)$listing['nightly_price'],0,',','.') ?>đ <span>/ đêm</span></p></div></article></div><?php endforeach; ?></div><?php endif; ?></div></section>

